tbl1.zoneIncome = function(arg1)
	local var1 = math.clamp(math.floor(arg1), 1, #tbl1.ZONE_GPM)
	local var2 = math.min(var1 + 1, #tbl1.ZONE_GPM)
	local var3 = tbl1.ZONE_GPM[var1] * tbl1.ZONE_DWELL[var1]
	return var3 * (tbl1.ZONE_GPM[var2] * tbl1.ZONE_DWELL[var2] / var3) ^ math.clamp(arg1 - var1, 0, 1)
end

