			return math.floor(var4 / var5 + 0.5) * var5
		end

		arg1.maxLevel = var15 + var17
	end

	local var22 = arg1.kind
	if not var22 then
		var22 = if arg1.maxLevel == 1 then "unlock" else "leveled"
	end

