tbl1.report = function()
	local tbl3 = {}
	local tbl4 = {}
	for k1, v1 in ipairs(tbl2) do
		local var1 = v1.currency or "gold"
		for i1 = 1, v1.maxLevel do
			local var3 = 1 < v1.maxLevel and v1.name .. " " .. i1 or v1.name
			if var1 == "gold" then
				local var4 = v1.gold(i1)
				if 0 >= var4 then
					continue
				end

				tbl3[#tbl3 + 1] = { label = var3, cost = var4 }
			else
				local var5 = i1
				tbl4[#tbl4 + 1] = string.format("%s %s %s", var3, fmt(v1[var1](var5)), var1)
			end
		end
	end

	table.sort(tbl3, function(arg1, arg2)
		return arg1.cost < arg2.cost
	end)

	local tbl5 = {}
	local tbl6 = {}
	local num1 = 0
	for i2 = 1, #tbl1.ZONE_GPM do
		local var6 = tbl1.ZONE_DWELL
		num1 = num1 + tbl1.ZONE_GPM[i2] * var6[i2]
		tbl6[i2] = num1
		tbl5[i2] = { count = 0, gold = 0, names = {} }
	end

	local tbl7 = { count = 0, gold = 0, names = {} }
	local num2 = 0
	for k2, v2 in ipairs(tbl3) do
		num2 = num2 + v2.cost
		local var7 = tbl7
		for i3 = 1, #tbl6 do
			if num2 > tbl6[i3] then
				continue
			end

			var7 = tbl5[i3]
			break
		end

		local var8 = var7.count + 1
		var7.count = var8
		var8 = var7.gold + v2.cost
		var7.gold = var8
		table.insert(var7.names, v2.label .. " " .. fmt(v2.cost))
	end

	print("[Upgrades] tree pacing: cheapest-first against the income banked at the intended pace (ZONE_GPM x ZONE_DWELL)")
	for k3, v3 in ipairs(tbl5) do
		local var9 = tbl1.ZONE_GPM[k3] * tbl1.ZONE_DWELL[k3]
		local var10 = v3.names
		local str1 = ", "
		local str2 = "  Z%d %-16s %2d levels %7s gold = %3.0f%% of the zone's %s | %s"
		local var11 = k3
		local var12 = tbl1.ZONE_NAMES[k3]
		local var13 = v3.count
		local var14 = fmt(v3.gold)
		local var15 = v3.gold / var9 * 100
		local var16 = fmt(var9)
		print(string.format(str2, var11, var12, var13, var14, var15, var16, table.concat(var10, str1)))
	end

	local var17 = tbl7.names
	local str3 = ", "
	local str4 = "  beyond Castle    %2d levels %7s gold | %s"
	local var18 = tbl7.count
	local var19 = fmt(tbl7.gold)
	print(string.format(str4, var18, var19, table.concat(var17, str3)))
	print("  rolls / gems: " .. table.concat(tbl4, "; "))
end

