	end

	for i1 = 1, 2 do
		if var3:NextNumber() >= (i1 == 1 and tbl1.SUPPLY_CHANCE or tbl1.SUPPLY_SECOND) then
			continue
		end

		local var10 = pickSupply(var3)
		tbl2[#tbl2 + 1] = { kind = var10.kind, id = var10.id, price = var10.price, limit = var10.limit or 2 }
	end

	local var11 = tbl1.SLOT_COUNT - #tbl2
	local var12 = var3:NextNumber()
	var4 = if var3:NextNumber() < tbl1.TOP_BAND_CHANCE then 1 else 0
	local var13 = math.min(tbl1.MID_BAND_COUNT, var11 - var4)
	local tbl3 = {}
	local tbl4 = { var11 - var4 - var13, var13, var4 }
	local var14 = var12 < tbl1.TRANSCENDENT_CHANCE
	local function pick(arg1)
		for i1 = 1, 25 do
			local var1 = arg1[var3:NextInteger(1, #arg1)]
			if tbl3[var1.id] then
				continue
			end

			tbl3[var1.id] = true
			return var1
		end

		return arg1[var3:NextInteger(1, #arg1)]
	end

	local tbl5 = {}
	for k1, v1 in ipairs(tbl1.BANDS) do
		local var16 = nil
		if k1 == (#tbl1.BANDS) then
			var16 = var14 and pool("transcendent", "transcendent") or pool("astral", "divine")
		else
			var16 = pool(v1.min, v1.max)
		end

		for i2 = 1, tbl4[k1] do
			tbl5[#tbl5 + 1] = pick(var16)
