		end

		if arg1.id ~= arg2.id then
			return arg1.id < arg2.id
		end

		local var1 = if arg1.shiny then 1 else 0
		return var1 < (if arg2.shiny then 1 else 0)
	end)

	return tbl2
end

return tbl1

