local tbl1 = {
	MAX_STARS = 3,
	COPIES_REQUIRED = 10,
	TOTAL_MULT = {
		common = 30,
		uncommon = 21,
		rare = 11,
		epic = 6.5,
		legendary = 3.25,
		mythical = 4.2,
		sacred = 4,
		astral = 3.6,
		divine = 4.5,
		transcendent = 2.75,
		celestial = 2,
	},
}

tbl1.totalFor = function(arg1)
	return tbl1.TOTAL_MULT[arg1] or 2
end

tbl1.multFor = function(arg1, arg2)
	arg2 = math.clamp(arg2 or 0, 0, tbl1.MAX_STARS)
	if arg2 == 0 then
		return 1
	end

	return 1 + (tbl1.totalFor(arg1) - 1) * arg2 / tbl1.MAX_STARS
end

tbl1.starsOf = function(arg1)
	return arg1 and arg1.ascension or 0
end

tbl1.candidates = function(arg1, arg2)
	local var1 = arg1
	var1 = var1 and arg1[arg2]
	if not var1 then
		return {}
	end

	local tbl1 = {}
	for k1, v1 in pairs(arg1) do
		if k1 == arg2 then
			continue
		end

		if v1.id ~= var1.id then
			continue
		end

		if v1.locked then
			continue
		end

		if v1.favorite then
			continue
		end

		if v1.shiny then
			continue
		end

		if (v1.ascension or 0) ~= 0 then
			continue
		end

		tbl1[#tbl1 + 1] = k1
	end

	table.sort(tbl1)
	return tbl1
end

tbl1.countFor = function(arg1, arg2)
	if not arg1 or (not arg1[arg2]) then
		return 0
	end

	return #tbl1.candidates(arg1, arg2)
end

return tbl1

