tbl1.gemsFor = function(arg1, arg2, arg3)
	local var1 = arg3
	return tbl1.GEMS_PER_MIN * (1 + tbl1.GEMS_ZONE_STEP * math.max((arg2 or 1) - 1, 0)) * ((var1 or tbl1.RATE) / tbl1.RATE) * (arg1 or 0)
end

tbl1.blankSession = function(arg1)
	local var1 = arg1
	arg1 = var1 or {}
	return {
		diceProgress = arg1.diceProgress or 0,
		gemProgress = arg1.gemProgress or 0,
		sessionGold = 0,
		sessionGems = 0,
		sessionExp = 0,
		sessionDice = 0,
		sessionMinutes = 0,
	}
end

return tbl1

