	pick = function(arg1, arg2)
		if not arg1 or #arg1 == 0 then
			return nil
		end

		if #arg1 == 1 then
			return arg1[1]
		end

		local var1 = arg1[math.random(1, #arg1)]
		local num1 = 0
		while var1 == arg2 and num1 < 8 do
			var1 = arg1[math.random(1, #arg1)]
			num1 = num1 + 1
		end

		return var1
	end,
}

